import{_ as a}from"./index-B0dzcLCb.js";import{m as c,q as t,o as e}from"./element-plus-BfJqCq-0.js";import"./vue-e8iUJMzd.js";import"./vendor-DJlWTEru.js";const v={class:"standard-container"},s={__name:"Standard",setup(b){return(i,d)=>(e(),c("div",v,[...d[0]||(d[0]=[t('<div class="page-header" data-v-edc8b82c><h2 data-v-edc8b82c>RECIST 1.1 评估标准</h2><p class="header-subtitle" data-v-edc8b82c>实体瘤疗效评价标准（Response Evaluation Criteria in Solid Tumors）第 1.1 版</p></div><div class="standard-content" data-v-edc8b82c><div class="section target-section" data-v-edc8b82c><h3 class="section-title" data-v-edc8b82c>靶病灶判定</h3><div class="standard-table" data-v-edc8b82c><table data-v-edc8b82c><thead data-v-edc8b82c><tr data-v-edc8b82c><th data-v-edc8b82c>类别</th><th data-v-edc8b82c>判定标准</th></tr></thead><tbody data-v-edc8b82c><tr data-v-edc8b82c><td data-v-edc8b82c><span class="badge cr" data-v-edc8b82c>CR 完全缓解</span></td><td data-v-edc8b82c>所有靶病灶消失；所有病理淋巴结短轴 &lt; 10 mm</td></tr><tr data-v-edc8b82c><td data-v-edc8b82c><span class="badge pr" data-v-edc8b82c>PR 部分缓解</span></td><td data-v-edc8b82c>靶病灶 SLD 较基线下降 ≥30%</td></tr><tr data-v-edc8b82c><td data-v-edc8b82c><span class="badge sd" data-v-edc8b82c>SD 疾病稳定</span></td><td data-v-edc8b82c>既达不到 PR（缩小不足），也未达 PD（增大不足），介于两者之间</td></tr><tr data-v-edc8b82c><td data-v-edc8b82c><span class="badge pd" data-v-edc8b82c>PD 疾病进展</span></td><td data-v-edc8b82c> 满足以下任一：<br data-v-edc8b82c> ① SLD 较研究期间最小值（nadir，含基线）增加 <strong data-v-edc8b82c>≥20%</strong> 且绝对值增加 <strong data-v-edc8b82c>≥5 mm</strong>；<br data-v-edc8b82c> ② 出现新病灶 </td></tr></tbody></table></div><div class="formula-box" data-v-edc8b82c><div class="formula-line" data-v-edc8b82c><code data-v-edc8b82c>SLD_baseline = Σ 各靶病灶最长径（基线）</code></div><div class="formula-line" data-v-edc8b82c><code data-v-edc8b82c>SLD_nadir = min(SLD_baseline, SLD_followup_1, SLD_followup_2, …)</code></div><div class="formula-line" data-v-edc8b82c><code data-v-edc8b82c>PR：(SLD_baseline − SLD_now) / SLD_baseline ≥ 0.30</code></div><div class="formula-line" data-v-edc8b82c><code data-v-edc8b82c>PD：(SLD_now − SLD_nadir) / SLD_nadir ≥ 0.20 AND (SLD_now − SLD_nadir) ≥ 5 mm → 或 出现新病灶</code></div></div></div><div class="section flowchart-section" data-v-edc8b82c><h3 class="section-title" data-v-edc8b82c>靶病灶疗效判定流程图</h3><div class="flowchart" data-v-edc8b82c><div class="fc-node fc-start" data-v-edc8b82c>计算 SLD（最长径之和）</div><div class="fc-arrow-down" data-v-edc8b82c></div><div class="fc-row" data-v-edc8b82c><div class="fc-branch fc-question" data-v-edc8b82c>所有靶病灶消失？</div><div class="fc-arrow-right" data-v-edc8b82c></div><div class="fc-result fc-cr" data-v-edc8b82c>CR（节点 &lt;10mm）</div></div><div class="fc-arrow-down fc-from-left" data-v-edc8b82c></div><div class="fc-row" data-v-edc8b82c><div class="fc-branch fc-question" data-v-edc8b82c>SLD 较基线 ↓≥30%？</div><div class="fc-arrow-right" data-v-edc8b82c></div><div class="fc-result fc-pr" data-v-edc8b82c>PR</div></div><div class="fc-arrow-down fc-from-left" data-v-edc8b82c></div><div class="fc-row" data-v-edc8b82c><div class="fc-branch fc-question" data-v-edc8b82c>较 nadir ↑≥20% 且 绝对↑≥5mm<br data-v-edc8b82c>或新病灶？</div><div class="fc-arrow-right" data-v-edc8b82c></div><div class="fc-result fc-pd" data-v-edc8b82c>PD</div></div><div class="fc-arrow-down fc-from-left" data-v-edc8b82c></div><div class="fc-row" data-v-edc8b82c><div class="fc-branch fc-empty" data-v-edc8b82c></div><div class="fc-arrow-right" data-v-edc8b82c></div><div class="fc-result fc-sd" data-v-edc8b82c>SD（介于 PR 与 PD 之间）</div></div><div class="fc-arrow-down" data-v-edc8b82c></div><div class="fc-node fc-end" data-v-edc8b82c>再与非靶病灶结果合并 → 总体疗效</div></div><p class="flowchart-note" data-v-edc8b82c>靶病灶疗效判定依赖 <strong data-v-edc8b82c>SLD 与 nadir 的比较</strong>：CR 优先判定，其次依次为 PR、PD，余者为 SD。</p></div><div class="section non-target-section" data-v-edc8b82c><h3 class="section-title" data-v-edc8b82c>非靶病灶判定</h3><div class="standard-table" data-v-edc8b82c><table data-v-edc8b82c><thead data-v-edc8b82c><tr data-v-edc8b82c><th data-v-edc8b82c>类别</th><th data-v-edc8b82c>判定标准</th></tr></thead><tbody data-v-edc8b82c><tr data-v-edc8b82c><td data-v-edc8b82c><span class="badge cr" data-v-edc8b82c>CR</span></td><td data-v-edc8b82c>所有非靶病灶消失；所有淋巴结短轴 &lt; 10 mm</td></tr><tr data-v-edc8b82c><td data-v-edc8b82c><span class="badge sd" data-v-edc8b82c>非CR/非PD (IR/SD)</span></td><td data-v-edc8b82c>存在 ≥1 个非靶病灶，或肿瘤标志物持续高于正常</td></tr><tr data-v-edc8b82c><td data-v-edc8b82c><span class="badge pd" data-v-edc8b82c>PD</span></td><td data-v-edc8b82c>已有非靶病灶明确进展，或出现任何新病灶</td></tr></tbody></table></div><div class="note-box" data-v-edc8b82c><p data-v-edc8b82c><strong data-v-edc8b82c>非靶 PD 的&quot;明确&quot;二字：</strong>非靶病灶的轻微增大不构成 PD，必须是<strong data-v-edc8b82c>明确（unequivocal）进展</strong>（如胸水从少量到大量、淋巴管炎从局限到弥漫）。系统实现时切忌把非靶尺寸小幅变化自动判为 PD。</p></div></div><div class="section confirmation-section" data-v-edc8b82c><h3 class="section-title" data-v-edc8b82c>确认规则（Confirmation）</h3><ul class="confirm-list" data-v-edc8b82c><li data-v-edc8b82c>在<strong data-v-edc8b82c>非随机试验</strong>中，<strong data-v-edc8b82c>CR 与 PR</strong>须在治疗后 <strong data-v-edc8b82c>≥4 周</strong>复查确认。</li><li data-v-edc8b82c><strong data-v-edc8b82c>随机试验</strong>可由方案决定是否需确认（多数不强制），但确认性的 PR 在后续访视中视为<strong data-v-edc8b82c>&quot;持续 PR&quot;</strong>，直至满足 PD 标准——后续判定参照 <strong data-v-edc8b82c>nadir 而非基线</strong>。</li><li data-v-edc8b82c><strong data-v-edc8b82c>PD 一般不需确认</strong>（除非征象模棱两可）。</li></ul></div><div class="section matrix-section" data-v-edc8b82c><h3 class="section-title" data-v-edc8b82c>整体评价决策矩阵</h3><div class="standard-table matrix-table" data-v-edc8b82c><table data-v-edc8b82c><thead data-v-edc8b82c><tr data-v-edc8b82c><th data-v-edc8b82c>Target 靶病灶</th><th data-v-edc8b82c>Non-Target 非靶病灶</th><th data-v-edc8b82c>New Lesion 新病灶</th><th data-v-edc8b82c>Overall 整体疗效</th></tr></thead><tbody data-v-edc8b82c><tr data-v-edc8b82c><td data-v-edc8b82c>CR</td><td data-v-edc8b82c>CR</td><td data-v-edc8b82c>No</td><td data-v-edc8b82c><span class="badge cr" data-v-edc8b82c>CR</span></td></tr><tr data-v-edc8b82c><td data-v-edc8b82c>CR</td><td data-v-edc8b82c>Non-CR/Non-PD</td><td data-v-edc8b82c>No</td><td data-v-edc8b82c><span class="badge pr" data-v-edc8b82c>PR</span></td></tr><tr data-v-edc8b82c><td data-v-edc8b82c>PR</td><td data-v-edc8b82c>Non-CR/Non-PD or CR</td><td data-v-edc8b82c>No</td><td data-v-edc8b82c><span class="badge pr" data-v-edc8b82c>PR</span></td></tr><tr data-v-edc8b82c><td data-v-edc8b82c>SD</td><td data-v-edc8b82c>Non-CR/Non-PD or CR</td><td data-v-edc8b82c>No</td><td data-v-edc8b82c><span class="badge sd" data-v-edc8b82c>SD</span></td></tr><tr data-v-edc8b82c><td data-v-edc8b82c>PD</td><td data-v-edc8b82c>Any</td><td data-v-edc8b82c>No / Yes</td><td data-v-edc8b82c><span class="badge pd" data-v-edc8b82c>PD</span></td></tr><tr data-v-edc8b82c><td data-v-edc8b82c>Any</td><td data-v-edc8b82c>PD</td><td data-v-edc8b82c>No / Yes</td><td data-v-edc8b82c><span class="badge pd" data-v-edc8b82c>PD</span></td></tr><tr data-v-edc8b82c><td data-v-edc8b82c>Any</td><td data-v-edc8b82c>Any</td><td data-v-edc8b82c>Yes</td><td data-v-edc8b82c><span class="badge pd" data-v-edc8b82c>PD</span> ← 最高优先级</td></tr></tbody></table></div></div><div class="section concepts-section" data-v-edc8b82c><h3 class="section-title" data-v-edc8b82c>关键概念</h3><div class="concept-grid" data-v-edc8b82c><div class="concept-card" data-v-edc8b82c><h4 data-v-edc8b82c>SLD（最长径之和）</h4><p data-v-edc8b82c>Sum of Longest Diameters —— 所有靶病灶最长直径之和。每次访视计算一次，用于与基线和历史最低值比较。</p></div><div class="concept-card" data-v-edc8b82c><h4 data-v-edc8b82c>Nadir（研究期间最低值）</h4><p data-v-edc8b82c>SLD_nadir = min(基线, 第1次随访, 第2次随访, ...)。PD 判定的参照基准是 <strong data-v-edc8b82c>nadir 不是基线</strong>。</p></div><div class="concept-card" data-v-edc8b82c><h4 data-v-edc8b82c>明确进展（Unequivocal）</h4><p data-v-edc8b82c>仅用于非靶病灶 PD 判定。要求&quot;明确&quot;的客观进展证据（如胸水明显增多），轻微尺寸变化不构成 PD。</p></div><div class="concept-card" data-v-edc8b82c><h4 data-v-edc8b82c>新病灶（New Lesion）</h4><p data-v-edc8b82c>治疗过程中新出现的任何病灶，无论大小、位置、发现方式（含 FDG-PET）。一旦确认即判为 PD（最高优先级一票否决）。</p></div></div></div></div>',2)])]))}},p=a(s,[["__scopeId","data-v-edc8b82c"]]);export{p as default};
